// Decide which sheet rows still need enriching.
const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');

s.updated = 0;
s.failed = 0;
s.loggedSample = 0;
s.failedProfiles = [];
s.pageFailedProfiles = 0;

const rows = $input.all().map((i) => i.json);
const val = (row, name) => (row[name] === undefined || row[name] === null ? '' : String(row[name]).trim());

let noUrl = 0;
let noOib = 0;
let alreadyDone = 0;
const out = [];

for (const row of rows) {
  const profile_url = val(row, 'Profile URL');
  const oib = val(row, 'OIB');
  const name = val(row, 'Name');

  // Any profile field already present means this row has been enriched.
  const enriched = val(row, 'Owner/Director') || val(row, 'Email') || val(row, 'MBS') ||
                   val(row, 'Founding Date') || val(row, 'NKD Code');

  if (!profile_url) { noUrl++; continue; }
  if (!oib) { noOib++; continue; }
  if (cfg.only_missing === true && enriched) { alreadyDone++; continue; }

  out.push({ json: { name, oib, profile_url, row_number: row.row_number, page: 0 } });
}

console.log('=== EmBRACE enrich: RUN START ===');
console.log(`Tab: "${cfg.source_tab}"  |  rows read: ${rows.length}`);
console.log(`Already enriched (skipped): ${alreadyDone}  |  no Profile URL: ${noUrl}  |  no OIB: ${noOib}`);

const limit = Number(cfg.max_rows) > 0 ? Number(cfg.max_rows) : out.length;
const selected = out.slice(0, limit);
const remaining = out.length - selected.length;

console.log(`Still needing enrichment: ${out.length} rows.`);
console.log(`This run will do ${selected.length} (~${Math.round(selected.length * 6 / 60)} min at 3s + request each).`);
if (remaining) {
  console.log(`${remaining} rows left after this run -- run the workflow again to continue.`);
  console.log(`At ${selected.length} per run that is about ${Math.ceil(remaining / selected.length)} more run(s).`);
}
if (!selected.length) console.log('Nothing to do -- every row already has profile data.');
s.remaining = remaining;
return selected;

// Parse a batch of profile pages and attach the fields to the matching rows.
//
// The HTTP node fetched several profiles in parallel. Responses are matched to
// rows by the OIB printed on the profile page itself, NOT by position: a
// position-based pairing that ever slipped would write one company's owner and
// email onto another company's row, silently and unrecoverably. Anything that
// cannot be matched with confidence is left blank and retried on a later run.
const bases = $('Loop Over Rows').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json);
const s = $getWorkflowStaticData('global');

const NAMED = {
  nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'",
  scaron: 'š', Scaron: 'Š', ccaron: 'č', Ccaron: 'Č', cacute: 'ć', Cacute: 'Ć',
  zcaron: 'ž', Zcaron: 'Ž', dstrok: 'đ', Dstrok: 'Đ', eacute: 'é', ndash: '-', mdash: '-',
};
const decode = (t) => t
  .replace(/&([A-Za-z][A-Za-z0-9]*);/g, (m, name) => (name in NAMED ? NAMED[name] : m))
  .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(Number(d)))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)));

const LABELS = {
  owner_director: ['Vlasnik', 'Vlasnici', 'Direktor', 'Direktori', 'Odgovorna osoba', 'Član uprave', 'Uprava'],
  email: ['E-mail', 'E-pošta', 'Email', 'E-mail adresa', 'Mail'],
  founding_date: ['Datum osnivanja', 'Datum upisa', 'Osnovan', 'Osnovana', 'Godina osnivanja'],
  nkd_code: ['NKD 2007', 'NKD', 'Šifra djelatnosti', 'Pretežita djelatnost', 'Djelatnost'],
  mbs: ['MBS', 'Matični broj subjekta', 'Matični broj'],
  oib: ['OIB', 'OIB broj', 'Osobni identifikacijski broj'],
};
const ALL_LABELS = new Set(Object.values(LABELS).flat().map((l) => l.toLowerCase()));
const EMAIL_RE = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/;
const esc = (v) => v.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function parseProfile(html) {
  const lines = decode(
    html
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<[^>]+>/g, '\n')
  ).split('\n').map((l) => l.replace(/\s+/g, ' ').trim()).filter(Boolean);

  const fromLabels = (labels) => {
    for (const label of labels) {
      const re = new RegExp('^' + esc(label) + '\\s*:?\\s*(.*)$', 'i');
      for (let i = 0; i < lines.length; i++) {
        const m = lines[i].match(re);
        if (!m) continue;
        const candidate = (m[1].trim() || lines[i + 1] || '').trim();
        if (candidate && candidate.length <= 300 && !ALL_LABELS.has(candidate.toLowerCase().replace(/:$/, ''))) {
          return candidate;
        }
      }
    }
    return '';
  };

  const out = {};
  for (const key of Object.keys(LABELS)) out[key] = fromLabels(LABELS[key]);

  const mailto = html.match(/mailto:([^"'?>\s]+)/i);
  if (mailto) {
    out.email = decode(mailto[1]).trim();
  } else if (!EMAIL_RE.test(out.email)) {
    const inLabel = out.email.match(EMAIL_RE);
    const anywhere = lines.join(' ').match(EMAIL_RE);
    out.email = (inLabel && inLabel[0]) || (anywhere && anywhere[0]) || '';
  }
  out.oib = String(out.oib || '').replace(/\D/g, '');
  return { fields: out, lines };
}

// Parse every response once.
const parsed = responses.map((raw) => {
  const html = typeof raw?.data === 'string' ? raw.data : (typeof raw === 'string' ? raw : '');
  if (!html || (raw && raw.error !== undefined)) {
    const reason = raw && raw.error !== undefined
      ? (typeof raw.error === 'string' ? raw.error : JSON.stringify(raw.error).slice(0, 200))
      : 'empty response';
    return { failed: true, reason };
  }
  const { fields, lines } = parseProfile(html);
  return { failed: false, fields, lines };
});

// Index the successful ones by the OIB printed on the page.
const byOib = new Map();
parsed.forEach((p, i) => {
  if (!p.failed && p.fields.oib) {
    if (!byOib.has(p.fields.oib)) byOib.set(p.fields.oib, i);
  }
});

const usedResponse = new Set();
const results = [];

for (const base of bases) {
  const wantOib = String(base.oib || '').replace(/\D/g, '');
  let idx = byOib.has(wantOib) ? byOib.get(wantOib) : -1;

  // A page that does not print its OIB can still be paired, but only when the
  // pairing is unambiguous: exactly one row and one response left over.
  if (idx === -1) {
    const freeParsed = parsed.map((p, i) => i).filter((i) => !usedResponse.has(i) && !parsed[i].failed && !parsed[i].fields.oib);
    const unmatchedBases = bases.filter((b) => {
      const o = String(b.oib || '').replace(/\D/g, '');
      return !byOib.has(o);
    });
    if (freeParsed.length === 1 && unmatchedBases.length === 1) idx = freeParsed[0];
  }

  const blank = { owner_director: '', email: '', founding_date: '', nkd_code: '', mbs: '' };

  if (idx === -1 || usedResponse.has(idx)) {
    const anyFailed = parsed.find((p) => p.failed);
    const reason = anyFailed ? anyFailed.reason : `no profile page matched OIB ${wantOib}`;
    s.failedProfiles = s.failedProfiles || [];
    s.failedProfiles.push({ name: base.name, oib: base.oib, url: base.profile_url, reason });
    console.log(`!! ${base.name} (OIB ${base.oib}): ${reason} -- row left blank, a later run will retry it.`);
    results.push({ json: { ...base, ...blank, profile_failed: true } });
    continue;
  }

  usedResponse.add(idx);
  const p = parsed[idx];
  const { oib: _pageOib, ...fields } = p.fields;

  const missing = Object.keys(blank).filter((k) => !fields[k]);
  if (missing.length && (s.loggedSample || 0) < 3) {
    s.loggedSample = (s.loggedSample || 0) + 1;
    console.log(`--- PROFILE PAGE TEXT SAMPLE (${base.name}) ---`);
    console.log(`missing fields: ${missing.join(', ')}`);
    console.log(p.lines.slice(0, 150).join(' | '));
    console.log('--- end sample ---');
  }

  results.push({ json: { ...base, ...fields, profile_failed: false } });
}

return results;

const s = $getWorkflowStaticData('global');
const items = $input.all().map((i) => i.json);

for (const c of items) {
  const filled = ['owner_director', 'email', 'founding_date', 'nkd_code', 'mbs'].filter((k) => c[k]);
  if (c.profile_failed) {
    s.failed = (s.failed || 0) + 1;
  } else {
    s.updated = (s.updated || 0) + 1;
  }
  console.log(`${c.name} (OIB ${c.oib}): ${filled.length}/5 -> ${filled.join(', ') || 'nothing'}`);
}
console.log(`  batch done -- ${s.updated || 0} updated, ${s.failed || 0} failed so far this run.`);
return $input.all();

const cfg = $('Config').first().json;
const s = $getWorkflowStaticData('global');

console.log('=== EmBRACE enrich: RUN COMPLETE ===');
console.log(`Tab: "${cfg.source_tab}"`);
console.log(`Rows updated: ${s.updated || 0}  |  profile fetches that failed: ${s.failed || 0}`);
if ((s.failedProfiles || []).length) {
  console.log('Failed profiles (rows left blank, safe to re-run):');
  console.log(JSON.stringify(s.failedProfiles, null, 2));
}
console.log('Run the workflow again to continue with the next chunk; already-enriched rows are skipped.');

return [{ json: {
  tab: cfg.source_tab,
  rows_updated: s.updated || 0,
  fetch_failures: s.failed || 0,
  rows_still_needing_enrichment: s.remaining || 0,
  failed_profiles: s.failedProfiles || [],
} }];
